'use strict';
const $=id=>document.getElementById(id), STORAGE='jibun-company-v1';
const difficulties={easy:{name:'かんたん',exp:300,icon:'☀'},normal:{name:'ふつう',exp:500,icon:'✦'},hard:{name:'がんばる',exp:800,icon:'⚡'}};
const day=()=>new Date().toLocaleDateString('sv-SE');
const initial=()=>({exp:0,day:day(),today:0,sales:0,tasks:[{id:'first1',name:'洗濯する',difficulty:'easy'},{id:'first2',name:'メールを返す',difficulty:'normal'},{id:'first3',name:'歯磨きする',difficulty:'easy'}]});
let state;try{state=JSON.parse(localStorage.getItem(STORAGE))}catch{}if(!state||!Number.isFinite(state.exp)||!Array.isArray(state.tasks))state=initial();
let busy=false,sound=false,audio;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function daily(){if(state.day!==day()){state.day=day();state.today=0;state.sales=0}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{}}
function growth(exp){let level=1,cost=1000,remaining=exp;while(remaining>=cost){remaining-=cost;level++;cost=level*1000}return{level,cost,remaining}}
function render(visualExp=state.exp){daily();const g=growth(visualExp);$('level').textContent=g.level;$('exp').textContent=g.remaining.toLocaleString();$('goal').textContent=g.cost.toLocaleString();$('progress').style.width=(g.remaining/g.cost*100)+'%';$('percent').textContent=Math.floor(g.remaining/g.cost*100)+'%';$('today').textContent=state.today;$('sales').textContent=state.sales.toLocaleString();$('count').textContent=state.tasks.length;$('office').className='office '+(g.level>=3?'lv3':g.level===2?'lv2':'');$('unlock').textContent=g.level===1?'🌿 観葉植物をお迎え':g.level===2?'💻 PCと棚を導入':'✦ 会社がもっと成長';$('office-note').textContent=g.level===1?'小さな一歩から、大きな会社へ。':g.level===2?'緑のあるオフィス。いい感じ。':'社長、会社らしくなってきました。';$('tasks').replaceChildren();for(const task of state.tasks){const d=difficulties[task.difficulty]||difficulties.normal;const button=document.createElement('button');button.className='task';button.setAttribute('aria-label',task.name+'を完了する。報酬'+d.exp+' EXP');const circle=document.createElement('span');circle.className='check';circle.textContent='✓';const details=document.createElement('span');details.className='task-details';const name=document.createElement('span');name.className='task-name';name.textContent=task.name;const badge=document.createElement('span');badge.className='task-difficulty';badge.textContent=d.icon+' '+d.name;details.append(name,badge);const reward=document.createElement('span');reward.className='task-exp';reward.textContent='+'+d.exp;const small=document.createElement('small');small.textContent='COMPANY EXP';reward.append(small);button.append(circle,details,reward);button.onclick=()=>complete(task.id);$('tasks').append(button)}if(!state.tasks.length){const e=document.createElement('div');e.className='empty';e.textContent='✦ 全案件、完了！社長、おつかれさま。\n次のビジネスチャンスを見つけよう。';$('tasks').append(e)}save()}
function tone(kind){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='level'?[523,659,784,1047,1319]:kind==='complete'?[523,659,784,1047]:[392,523,784];notes.forEach((freq,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(0,audio.currentTime+i*.09);gain.gain.linearRampToValueAtTime(.11,audio.currentTime+i*.09+.015);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+i*.09+.24);osc.connect(gain);gain.connect(audio.destination);osc.start(audio.currentTime+i*.09);osc.stop(audio.currentTime+i*.09+.25)})}catch{}}
$('sound').onclick=()=>{sound=!sound;$('sound').querySelector('span').textContent=sound?'ON':'OFF';$('sound').setAttribute('aria-label','効果音を'+(sound?'オフ':'オン')+'にする');if(sound)tone('order')};
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const praise=['社長、本日も見事な仕事ぶりです。','素晴らしい成果です、社長。','またひとつ、会社が成長しました。','本日の業務、無事完遂。','この調子で世界を取りにいきましょう。','小さな「できた」が、会社を育てる。','取締役会、満場一致で拍手です。','この一歩、弊社にとっては大きな一歩。'];
let lastPraise=-1;
function compliment(){let i;do{i=Math.floor(Math.random()*praise.length)}while(i===lastPraise);lastPraise=i;return praise[i]}
function confetti(amount,active){if(reduced)return;const c=$('confetti'),ctx=c.getContext('2d');if(!ctx)return;const w=innerWidth,h=innerHeight,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const colors=['#fff5b5','#fffdf1','#f7a8ce','#70a3dc','#f2894e','#527958'];const pieces=Array.from({length:amount},(_,i)=>({x:w/2,y:h*.43,vx:(Math.random()-.5)*27,vy:-Math.random()*23-3,rot:Math.random()*6,size:5+Math.random()*8,color:colors[i%colors.length],star:i%5===0}));let start,previous;function frame(t){if(!active())return;start??=t;const dt=Math.min((t-(previous||t))/16.67,2);previous=t;ctx.clearRect(0,0,w,h);for(const p of pieces){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.23*dt;p.rot+=.08*dt;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=p.color;if(p.star){ctx.beginPath();for(let i=0;i<8;i++){const r=i%2?p.size*.22:p.size;const a=i*Math.PI/4;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill()}else ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*.6);ctx.restore()}if(t-start<2300)requestAnimationFrame(frame)}requestAnimationFrame(frame)}
function celebrate(kind,name,value,from,difficulty='normal'){
 return new Promise(resolve=>{
 const overlay=$('celebration'),isOrder=kind==='order',isLevel=kind==='level',hard=difficulty==='hard';
 let active=true;const timers=[];const later=(fn,ms)=>timers.push(setTimeout(()=>{if(active)fn()},ms));
 const finish=()=>{if(!active)return;active=false;timers.forEach(clearTimeout);overlay.hidden=true;overlay.onclick=null;overlay.onkeydown=null;document.querySelector('.app').inert=false;const ctx=$('confetti').getContext('2d');if(ctx)ctx.clearRect(0,0,$('confetti').width,$('confetti').height);if(navigator.vibrate)navigator.vibrate(0);resolve()};
 overlay.className='celebration '+(isOrder?'order':isLevel?'levelup':'complete')+' difficulty-'+difficulty+' anticipatory';
 overlay.hidden=false;document.querySelector('.app').inert=true;
 $('celebrate-kicker').textContent=isOrder?'A NEW CHANCE...':isLevel?'SOMETHING BIG IS HAPPENING...':'MISSION COMPLETE...';
 $('celebrate-icon').textContent=isOrder?'✦':isLevel?'♛':'✓';
 const title=isOrder?(hard?'SPECIAL PROJECT ACQUIRED!!':difficulty==='normal'?'BIG PROJECT！':'新規案件獲得！'):isLevel?'COMPANY LEVEL UP！':'案 件 完 遂';
 $('celebrate-title').replaceChildren();if(!isOrder&&!isLevel){[...title].forEach((letter,i)=>{const span=document.createElement('span');span.textContent=letter;span.style.setProperty('--letter',i);$('celebrate-title').append(span)})}else $('celebrate-title').textContent=title;
 $('celebrate-name').textContent=name;
 $('celebrate-message').textContent=isOrder?'完了時の報酬。さあ、ひと仕事！':isLevel?'あなたの会社が少し大きくなりました。':compliment();
 $('celebrate-hint').textContent=isOrder?"LET’S GET TO WORK.":isLevel?'新しいオフィスを見てみよう。':'本日の売上 +'+value.toLocaleString()+' EXP';
 $('reward').replaceChildren();const number=document.createElement('span'),unit=document.createElement('small');$('reward').append(number,unit);
 number.textContent=isLevel?'Lv.'+from+' → Lv.'+value:'+0';unit.textContent=isLevel?(value===2?'🌿 観葉植物が仲間入り':value===3?'💻 PCと棚が仲間入り':'会社がさらに成長！'):isOrder?'EXPECTED COMPANY EXP':'COMPANY EXP';
 overlay.onclick=finish;overlay.onkeydown=e=>{if(['Escape','Enter',' '].includes(e.key)){e.preventDefault();finish()}};overlay.focus();
 const reveal=()=>{overlay.classList.remove('anticipatory');overlay.classList.add('impact');$('celebrate-kicker').textContent=isOrder?'NEW BUSINESS OPPORTUNITY':isLevel?'YOUR COMPANY IS GROWING':'GREAT JOB, BOSS!';tone(kind);if(navigator.vibrate&&!reduced)navigator.vibrate(isLevel?[35,45,50,45,90]:isOrder?[20,35,30]:[40,30,70]);confetti(isLevel?250:isOrder?(hard?150:difficulty==='normal'?110:65):(hard?225:difficulty==='normal'?165:100),()=>active);if(!isLevel){const start=performance.now();const tick=now=>{if(!active)return;const p=reduced?1:Math.min((now-start)/720,1);number.textContent='+'+Math.round(value*(1-Math.pow(1-p,3))).toLocaleString();if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)}later(()=>overlay.classList.add('settled'),850)};
 if(reduced){reveal();later(finish,1300)}else{const anticipation=isOrder?(hard?650:450):isLevel?650:550;later(reveal,anticipation);later(finish,isOrder?(hard?2850:2550):isLevel?3100:2900)}
 })
}
function tweenGrowth(from,to,duration=650){return new Promise(resolve=>{if(reduced||from===to){render(to);resolve();return}const start=performance.now();$('progress').style.transition='none';function frame(now){const p=Math.min((now-start)/duration,1),exp=Math.round(from+(to-from)*(1-Math.pow(1-p,3))),g=growth(exp);$('exp').textContent=g.remaining.toLocaleString();$('progress').style.width=(g.remaining/g.cost*100)+'%';$('percent').textContent=Math.floor(g.remaining/g.cost*100)+'%';if(p<1)requestAnimationFrame(frame);else{$('progress').style.transition='';render(to);resolve()}}requestAnimationFrame(frame)})}
async function animateHome(from,to){const old=growth(from),next=growth(to);render(from);if(next.level>old.level&&!reduced){const boundary=from+old.cost-old.remaining;await tweenGrowth(from,boundary-1,520);$('exp').textContent=old.cost.toLocaleString();$('progress').style.width='100%';await wait(160);render(boundary);await tweenGrowth(boundary,to,620)}else await tweenGrowth(from,to,850)}
$('new-task').onclick=()=>{if(busy)return;$('new-dialog').showModal();setTimeout(()=>$('task-name').focus(),60)};$('close-dialog').onclick=()=>$('new-dialog').close();$('new-dialog').onclick=e=>{if(e.target===$('new-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
$('task-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const name=$('task-name').value.trim();if(!name){$('task-name').setCustomValidity('案件名を入力してください');$('task-name').reportValidity();return}busy=true;const difficulty=new FormData(e.target).get('difficulty');const id=globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();state.tasks.push({id,name,difficulty});save();$('new-dialog').close();e.target.reset();render();await celebrate('order',name,difficulties[difficulty].exp,undefined,difficulty);busy=false;$('new-task').focus()};$('task-name').oninput=()=>$('task-name').setCustomValidity('');
async function complete(id){if(busy)return;const index=state.tasks.findIndex(t=>t.id===id);if(index<0)return;busy=true;daily();const task=state.tasks[index],d=difficulties[task.difficulty]||difficulties.normal,previousExp=state.exp,old=growth(previousExp).level;state.tasks.splice(index,1);state.exp+=d.exp;state.today++;state.sales+=d.exp;save();try{if(!reduced)await wait(90);await celebrate('complete',task.name,d.exp,undefined,task.difficulty);const next=growth(state.exp).level;if(next>old)await celebrate('level','おめでとう、社長！',next,old,task.difficulty);await animateHome(previousExp,state.exp);$('today').parentElement.classList.remove('pop');void $('today').offsetWidth;$('today').parentElement.classList.add('pop')}finally{busy=false;render();($('tasks').querySelector('button')||$('new-task')).focus()}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!busy)render()});render();
